def slug(s):
    return re.sub(r"[^a-z0-9]+", "-", s.lower()).strip("-")[:48].strip("-")

def main():
    eps, n = [], 0
    for code, name, short, hw, color, resume in MODULES:
        for i, (title, learn, build, ehw, srcs) in enumerate(EPISODES[code], 1):
            n += 1
            for s in srcs:
                assert s in SOURCES, (code, title, s)
            folder = f"{code}-{short}"
            sl = slug(title)
            eps.append(dict(
                ep=n, code=f"{code}E{i:02d}", module=code, module_name=name, mod_ep=i,
                title=title, slug=sl, learn=learn, build=build, hardware=ehw, sources=srcs,
                folder=folder,
                prep=f"prep/{folder}/E{i:02d}-{sl}.md",
                code_file=f"code/{folder}/e{i:02d}_{sl.replace('-', '_')}.py",
                explainer=f"explainers/scenes/{code.lower()}e{i:02d}_{sl.replace('-', '_')[:32]}.py",
            ))
    out = dict(
        series="LLMs from First Principles",
        modules=[dict(code=c, name=nm, short=s, hardware=h, color=col, resume=r,
                      episodes=len(EPISODES[c])) for c, nm, s, h, col, r in MODULES],
        sources={k: dict(name=v[0], kind=v[1], url=v[2]) for k, v in SOURCES.items()},
        episodes=eps,
    )
    p = f"{ROOT}/curriculum/curriculum.json"
    json.dump(out, open(p, "w"), indent=1)
    print(f"{len(eps)} episodes, {len(MODULES)} modules, {len(SOURCES)} sources -> {p}")

if __name__ == "__main__":
    main()
